<?php
declare(strict_types=1);require_once dirname(__DIR__).'/includes/auth.php';require_once __DIR__.'/layout.php';require_once dirname(__DIR__).'/services/student_portal.php';$current=tuman_require_role('STUDENT');$batches=[];$error=null;try{$batches=tuman_student_batches(tuman_database(),$current['id']);}catch(Throwable $e){error_log($e->getMessage());$error='Your batches cannot be loaded right now.';}tuman_student_page_start('My batches');
?>
<h1>My batches</h1><p>These are the batches you are enrolled in. Individual lessons remain separate.</p><?php if($error):?><p role="alert"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></p><?php elseif($batches===[]):?><p>You are not currently enrolled in a batch.</p><?php else:?><div style="overflow-x:auto"><table><thead><tr><th>Batch</th><th>Teacher</th><th>Objective</th><th>Enrolled</th><th>Status</th></tr></thead><tbody><?php foreach($batches as $batch):?><tr><td><?=htmlspecialchars($batch['batch_name'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars(trim($batch['teacher_first_name'].' '.($batch['teacher_last_name']??'')),ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($batch['objective']??'—',ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($batch['enrolled_on'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($batch['membership_status'],ENT_QUOTES,'UTF-8')?></td></tr><?php endforeach;?></tbody></table></div><?php endif;tuman_student_page_end(); ?>
